{
  const el = document.getElementById("dm-t-0-y7if");
  if (el) {
    gsap.set(el, { autoAlpha: 0, pointerEvents: "none" });
    tl.set(el, { autoAlpha: 1 }, 1.000);
    const tmTl = gsap.timeline();

tmTl.fromTo(el, { opacity: 0 }, { opacity: 1, duration: 0.8 });
const card = el.querySelector(".dm-3d-card");
if (card) {
  tmTl.fromTo(card, { scale: 0.85, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.9, ease: "power2.out" }, "<");
}
const flare = el.querySelector(".dm-lens-flare");
if (flare) {
  tmTl.fromTo(flare, { scaleX: 0, opacity: 0 }, { scaleX: 1.6, opacity: 1, duration: 0.4, ease: "power3.out" }, 0.2);
  tmTl.to(flare, { scaleX: 0.6, opacity: 0.35, duration: 0.6, ease: "power2.inOut" }, 0.6);
}
tmTl.to(el.querySelectorAll(".dm-ring-cw"), { rotation: 360, duration: 8, ease: "none", repeat: 6, transformOrigin: "120px 120px" }, 0);
tmTl.to(el.querySelectorAll(".dm-ring-ccw"), { rotation: -360, duration: 6, ease: "none", repeat: 7, transformOrigin: "120px 120px" }, 0);
const embers = el.querySelectorAll(".dm-ember");
if (embers && embers.length > 0) {
  embers.forEach((em, idx) => {
    tmTl.fromTo(em, { opacity: 0, y: 0, scale: 0.5 }, { opacity: 0.9, y: -60 - (idx * 15), scale: 1.2, duration: 2.2 + (idx * 0.3), ease: "power1.out", repeat: 3, stagger: 0.2 }, 0.3);
  });
}

    tl.add(tmTl, 1.000);
    tl.to(el, { autoAlpha: 0, scale: 0.88, duration: 0.5, ease: "power2.in" }, 5.300);
    tl.set(el, { autoAlpha: 0 }, 5.800);
  }
}

